<?php /** @var array $rows @var string $st */ ?>
<div class="tabs"><?php foreach (['pending' => 'Awaiting approval', 'issued' => 'Unused', 'used' => 'Used', 'cancelled' => 'Cancelled', 'expired' => 'Expired', 'all' => 'All'] as $k => $l): ?><a href="<?= e(url('admin/loyalty/redemptions?status=' . $k)) ?>" class="<?= $st === $k ? 'on' : '' ?>"><?= $l ?></a><?php endforeach; ?></div>
<section class="apanel flush"><div class="tbl-wrap"><table class="tbl"><thead><tr><th>Date</th><th>Customer</th><th>Reward</th><th class="r">Points</th><th>Voucher</th><th>Status</th><th></th></tr></thead><tbody>
<?php foreach ($rows as $r): ?><tr><td class="muted"><?= e(fmt_date($r->created_at)) ?></td><td><b><a href="<?= e(url('admin/loyalty/members/' . $r->user_id)) ?>"><?= e($r->customer) ?></a></b><small><?= e($r->email) ?></small></td><td><?= e($r->reward) ?></td><td class="r"><?= number_format($r->points) ?></td><td><code><?= e($r->code) ?></code><?= $r->expires_at ? '<small>expires ' . e(fmt_date($r->expires_at, false)) . '</small>' : '' ?></td><td><span class="pill"><?= e($r->status) ?></span></td>
<td class="r"><?php if ($r->status === 'pending'): ?><form method="post" action="<?= e(url('admin/loyalty/redemptions/' . $r->id . '/approve')) ?>" style="display:inline"><?= csrf_field() ?><button class="btn sm">Approve</button></form><form method="post" action="<?= e(url('admin/loyalty/redemptions/' . $r->id . '/reject')) ?>" style="display:inline"><?= csrf_field() ?><button class="btn sm ghost danger" data-confirm="Reject and return the points?">Reject</button></form>
<?php elseif ($r->status === 'issued'): ?><form method="post" action="<?= e(url('admin/loyalty/redemptions/' . $r->id . '/cancel')) ?>"><?= csrf_field() ?><button class="btn sm ghost danger" data-confirm="Cancel, disable the voucher and return the points?">Cancel &amp; refund points</button></form><?php endif; ?></td></tr>
<?php endforeach; ?><?php if (!$rows): ?><tr><td colspan="7" class="empty">Nothing here.</td></tr><?php endif; ?></tbody></table></div></section>
